<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue';import {useRouter} from 'vue-router';import {api,allPages} from '../services/api';import {usePage} from '../services/usePage';import Notice from '../components/Notice.vue';import {ScanLine,Upload,Camera,X} from 'lucide-vue-next'
const models=ref<any[]>([]),model=ref(''),confidence=ref(.25),files=ref<File[]>([]),previews=ref<string[]>([]),video=ref<HTMLVideoElement|null>(null),camera=ref(false),router=useRouter();let stream:MediaStream|null=null;const {error,success,busy,act}=usePage()
onMounted(()=>act(async()=>{models.value=await allPages('models/');model.value=models.value.find(m=>m.active)?.id||models.value[0]?.id||''}));onBeforeUnmount(()=>{stop();previews.value.forEach(URL.revokeObjectURL)})
function pick(list:File[]){previews.value.forEach(URL.revokeObjectURL);files.value=list;previews.value=list.slice(0,12).map(f=>URL.createObjectURL(f))}
const submit=()=>act(async()=>{const form=new FormData();form.append('model',model.value);form.append('confidence',String(confidence.value));files.value.forEach(f=>form.append('files',f));const {data}=await api.post('inspections/',form);router.push(data.length===1?'/inspections/'+data[0].id:'/inspections')})
const start=()=>act(async()=>{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});camera.value=true;await new Promise(r=>setTimeout(r,0));if(video.value){video.value.srcObject=stream;await video.value.play()}})
function stop(){stream?.getTracks().forEach(t=>t.stop());stream=null;camera.value=false}
function capture(){if(!video.value)return;const canvas=document.createElement('canvas');canvas.width=video.value.videoWidth;canvas.height=video.value.videoHeight;canvas.getContext('2d')!.drawImage(video.value,0,0);canvas.toBlob(blob=>{if(blob)pick([...files.value,new File([blob],`captura-${Date.now()}.jpg`,{type:'image/jpeg'})]);stop()},'image/jpeg',.95)}
</script>
<template><div class="mb-7"><h1 class="heading">Una nueva mirada.</h1><p class="subheading">Analiza imágenes de paltas Hass con un modelo entrenado para detectar roña superficial.</p></div><Notice :error="error" :success="success"/><div class="grid items-start gap-6 lg:grid-cols-[1.6fr_1fr]"><section class="card"><label class="flex min-h-64 cursor-pointer flex-col items-center justify-center rounded-xl border-2 border-dashed border-emerald-200 bg-[#f7faf2] p-6 text-center" @dragover.prevent @drop.prevent="pick(Array.from($event.dataTransfer?.files||[]))"><div class="mb-4 rounded-2xl bg-white p-4 shadow-sm"><Upload class="text-emerald-700" :size="28"/></div><span class="text-lg font-semibold text-forest">Arrastra tus imágenes aquí</span><span class="mt-2 text-xs text-slate-500">o selecciona archivos de tu equipo</span><span class="mt-5 text-[10px] text-slate-400">JPG · PNG · WEBP / hasta 20 MB por imagen</span><input class="sr-only" type="file" accept="image/jpeg,image/png,image/webp" multiple @change="pick(Array.from(($event.target as HTMLInputElement).files||[]))"/></label><div class="mt-4 flex items-center justify-between"><p class="text-xs text-slate-500">{{files.length}} archivo(s) seleccionado(s)</p><button @click="start" class="btn-secondary"><Camera :size="16"/>Usar cámara</button></div><div v-if="previews.length" class="mt-5 grid grid-cols-4 gap-3"><img v-for="(url,i) in previews" :key="url" :src="url" :alt="files[i]?.name" class="aspect-square rounded-lg border border-slate-100 object-contain"/></div><div v-if="camera" class="mt-4"><video ref="video" autoplay playsinline muted class="w-full rounded-xl"></video><div class="mt-2 flex gap-2"><button class="btn" @click="capture">Capturar foto</button><button class="btn-secondary" @click="stop">Cerrar cámara</button></div></div></section><form @submit.prevent="submit" class="card space-y-5"><h2 class="font-semibold">Configuración de inspección</h2><div><label class="label">Modelo</label><select v-model="model" class="input" required><option value="">Seleccionar modelo</option><option v-for="m in models" :key="m.id" :value="m.id">{{m.name}}{{m.active?' · Activo':''}}</option></select><p v-if="!models.length" class="mt-2 text-xs text-amber-700">Primero debes completar un entrenamiento.</p></div><div><label class="label">Umbral de confianza · {{confidence}}</label><input type="range" min=".01" max=".99" step=".01" v-model.number="confidence" class="w-full accent-emerald-700"/><p class="mt-2 text-xs leading-5 text-slate-400">El umbral filtra detecciones. Mantén un valor fijo para las comparaciones experimentales.</p></div><button class="btn w-full !py-3.5" :disabled="busy||!model||!files.length"><ScanLine :size="17"/>{{busy?'Enviando…':'Analizar imágenes'}}</button><div class="rounded-xl bg-amber-50 p-4 text-xs leading-6 text-amber-800">La ausencia de detecciones no garantiza que la palta esté sana. La confianza del modelo no es un diagnóstico confirmado.</div></form></div></template>
